MATCH (c:Company)-[:hasCEO]->(p:Person)
WHERE EXISTS {
  MATCH (a:Company {name: "Agrofert"})-[:hasBoardMember]->(p)
}
WITH c, count(DISTINCT p) AS ceo_count
RETURN c.name, ceo_count

MATCH (c:Company {name: "General Motors"})-[:hasBoardMember]->(p:Person)
WHERE NOT EXISTS {
  MATCH (c)-[r:hasBoardMember]->(p)
  WHERE r.end_year IS NOT NULL
}
RETURN DISTINCT p.name
